Q: finding out which object to point to in javascript A: <p>One fact here:  javascript objects can be reffered to by multiple names.  Given that, your question is a bit perplexing.</p>

<p>See this question for some discussion: <a href="https://stackoverflow.com/questions/789675/how-to-get-class-objects-name-as-a-string-in-javascript">How to get class object&#39;s name as a string in Javascript?</a></p>

<p>Perhaps a better method would be to send the function the object as a parameter.</p>

<p>My example code below, would alert "apropdiffhouse" twice for instance.</p>

<p>working example: <a href="http://jsfiddle.net/MarkSchultheiss/pCtaH/" rel="nofollow noreferrer">http://jsfiddle.net/MarkSchultheiss/pCtaH/</a></p>

<pre><code>var appointment = {
    Id: "newId",
    Name: "newN",
    MyProp: "newP"
};
var CurrentAppointments = {
    appoint: [appointment]
};
CurrentAppointments[0] = appointment;
CurrentAppointments[1] = appointment;
CurrentAppointments[2] = appointment;


var Appointments02092012 = {
    appoint: [appointment, appointment, appointment]
};

Appointments02092012[1] = {
    Id: "myid",
    Name: "myName",
    MyProp: "aprop"
};
var AppointmentsToday = {};
var Appointments02102012 = {};
var Appointments02092012 = {};
Appointments02102012[1] = appointment;
Appointments02102012[1] = {
    Id: "mynewid",
    Name: "mynewName",
    MyProp: "apropdiff"
};

function ProcessNewAppointments(TheAppointments) {
    CurrentAppointments = TheAppointments;
}

function SomeFunctionThatDoesWork(workingAppointment) {
    var SomeValue = "house";
    var i = 1;
    CurrentAppointments = workingAppointment;
    CurrentAppointments[i].MyProp = CurrentAppointments[i].MyProp +SomeValue;
    ProcessNewAppointments(workingAppointment);
}

function CallingFunction() {
       ProcessNewAppointments(Appointments02102012);
}
CallingFunction();
var currentIndex = 1;
SomeFunctionThatDoesWork(CurrentAppointments);
alert(CurrentAppointments[currentIndex].MyProp);
alert(Appointments02102012[currentIndex].MyProp);
</code></pre>
